package com.samreen.auditlog.facade;
import com.samreen.auditlog.entity.AuditRecordEntity; import com.samreen.auditlog.repository.AuditRecordRepository; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant;
@Service public class ComplianceReportFacadeImpl implements ComplianceReportFacade { private final AuditRecordRepository repository; public ComplianceReportFacadeImpl(AuditRecordRepository r){repository=r;} @PreAuthorize("hasRole('COMPLIANCE_REVIEWER')") @Transactional(readOnly=true) public Page<ComplianceAccessReport> accessReport(String actorId,String resourceId,String eventType,Instant from,Instant to,int page,int size){if(page<0||size<1||size>100)throw new IllegalArgumentException("Page size must be between 1 and 100");Specification<AuditRecordEntity> s=Specification.where((r,q,b)->b.like(r.get("eventType"),"%ACCESS%"));if(actorId!=null)s=s.and((r,q,b)->b.equal(r.get("actorId"),actorId));if(resourceId!=null)s=s.and((r,q,b)->b.equal(r.get("resourceId"),resourceId));if(eventType!=null)s=s.and((r,q,b)->b.equal(r.get("eventType"),eventType));if(from!=null)s=s.and((r,q,b)->b.greaterThanOrEqualTo(r.get("eventTimestamp"),from));if(to!=null)s=s.and((r,q,b)->b.lessThan(r.get("eventTimestamp"),to));return repository.findAll(s,PageRequest.of(page,size,Sort.by("sequenceNumber").ascending())).map(e->new ComplianceAccessReport(e.getId(),e.getSequenceNumber(),e.getActorId(),e.getResourceId(),e.getEventType(),e.getEventTimestamp(),e.getContentHash()));}}
